/bin/bash -lc "python - <<'PY'
from decimal import Decimal, getcontext
from pathlib import Path
getcontext().prec = 40
vals = {'fungi': [], 'animals': []}
with Path('/workspace/tmp/phykit_metrics_grouped.tabular').open(encoding='utf-8') as fh:
    header = fh.readline().rstrip('\\n').split('\\t')
    idx = {name:i for i,name in enumerate(header)}
    for line in fh:
        row = line.rstrip('\\n').split('\\t')
        if len(row) "'!= len(header) or row[idx['"'status']] "'!= '"'ok':
            continue
        vals[row[idx['group']]].append(Decimal(row[idx['value']]))

def median(xs):
    ys = sorted(xs)
    n = len(ys)
    if n % 2:
        return ys[n//2]
    return (ys[n//2-1] + ys[n//2]) / Decimal(2)
med = {k:median(v) for k,v in vals.items()}
print('counts', {k:len(v) for k,v in vals.items()})
print('medians', med)
print('fungi_over_animals', med['fungi']/med['animals'])
print('animals_over_fungi', med['animals']/med['fungi'])
PY"

